/** Brand mark for a review platform name */
export function PlatformLogo({ platform, size = 18 }: { platform: string; size?: number }) {
  if (platform === "Google") return <GoogleG size={size} />;
  if (platform === "Facebook") return <FacebookLogo size={size} />;
  if (platform === "Yelp") return <YelpLogo size={size} />;
  return null;
}
